import{_ as e,o as n,c as r,a2 as l}from"./chunks/framework.F7eQ-ohH.js";const d="/bzygq/assets/da620dcfa20b4419ae4eb9d3e93b82f8.BDA7Dcv-.png",a="/bzygq/assets/c4688ee0c90244b78ca929176025836f.DNI7zp_Z.png",c=JSON.parse('{"title":"05、MySQL 日志体系：binlog、redo log 与 undo log","description":"","frontmatter":{},"headers":[],"relativePath":"Java面试问题汇总/MySQL/05、MySQL 日志体系：binlog、redo log 与 undo log.md","filePath":"Java面试问题汇总/MySQL/05、MySQL 日志体系：binlog、redo log 与 undo log.md","lastUpdated":1788929995000}'),t={name:"Java面试问题汇总/MySQL/05、MySQL 日志体系：binlog、redo log 与 undo log.md"};function g(i,o,p,b,u,h){return n(),r("div",null,[...o[0]||(o[0]=[l('<h1 id="_05、mysql-日志体系-binlog、redo-log-与-undo-log" tabindex="-1">05、MySQL 日志体系：binlog、redo log 与 undo log <a class="header-anchor" href="#_05、mysql-日志体系-binlog、redo-log-与-undo-log" aria-label="Permalink to &quot;05、MySQL 日志体系：binlog、redo log 与 undo log&quot;">​</a></h1><p>MySQL 日志体系是数据库把“内存中的修改”变成“可恢复、可复制、可回滚结果”的关键机制。面试里最常考的三类日志是 binlog、redo log 和 undo log：binlog 位于 Server 层，记录逻辑变更，服务于复制、订阅和按时间点恢复；redo log 位于 InnoDB 引擎层，记录数据页的物理修改，服务于崩溃恢复和事务持久性；undo log 记录修改前的旧版本，服务于事务回滚和 MVCC 一致性读。</p><p>日志不是为了“多存一份操作记录”这么简单。数据库写入时会同时面对性能和可靠性两个目标：如果每次提交都把分散的数据页立即刷盘，随机 IO 成本很高；如果只改内存又不落盘，宕机后数据会丢失。MySQL 的日志体系正是为了在这两个目标之间取得平衡：先用顺序写日志固定恢复依据，再把数据页刷盘延后到更合适的时机。</p><h2 id="一、日志体系解决什么问题" tabindex="-1">一、日志体系解决什么问题 <a class="header-anchor" href="#一、日志体系解决什么问题" aria-label="Permalink to &quot;一、日志体系解决什么问题&quot;">​</a></h2><p>从工程角度看，MySQL 日志至少解决四类问题。第一是崩溃恢复，数据库异常重启后要知道哪些已提交修改必须重放，哪些未提交修改必须撤销。第二是事务回滚，业务执行到一半失败时，要能把已经修改的行恢复到旧值。第三是主从复制，主库的逻辑变更要能发送给从库重放。第四是审计、诊断和性能分析，例如错误日志、慢查询日志可以帮助定位实例故障和慢 SQL。</p><p><img src="'+d+'" alt="images/mysql-log-types-map.png"></p><p>images/mysql-log-types-map.png</p><p>这张旧图适合用来做日志体系的入口图：先把错误日志、查询日志、慢查询日志、binlog、redo log、undo log 等常见日志放到同一张地图里，再重点区分面试高频的三类事务相关日志。</p><p>这些日志的责任边界不同，不能混为一谈。redo log 解决的是 InnoDB 数据页是否能恢复到已提交状态；undo log 解决的是事务能否撤销以及旧版本能否被读到；binlog 解决的是 MySQL Server 层的逻辑变更能否被复制和恢复。把这三条线分清楚，后面理解两阶段提交、MVCC 和主从复制就会顺很多。</p><p><img src="'+a+'" alt="images/mysql-05-log-2pc.png"></p><p>images/mysql-05-log-2pc.png</p><p>上图可以按一条更新语句来理解：执行器调用 InnoDB 修改 Buffer Pool 中的数据页，InnoDB 先写 undo 以便回滚，再写 redo 并进入 prepare；Server 层写 binlog；最后 InnoDB 把 redo 标记为 commit。数据页本身可以晚一点刷盘，但只要日志顺序正确，崩溃恢复就有依据。</p><h2 id="二、binlog-server-层的逻辑变更日志" tabindex="-1">二、binlog：Server 层的逻辑变更日志 <a class="header-anchor" href="#二、binlog-server-层的逻辑变更日志" aria-label="Permalink to &quot;二、binlog：Server 层的逻辑变更日志&quot;">​</a></h2><p>binlog 是 MySQL Server 层的二进制日志，用来记录数据库执行过的逻辑变更。它不属于某一个存储引擎，因此 InnoDB、MyISAM 等引擎都可以配合 binlog 工作。主从复制、基于时间点的数据恢复、数据订阅工具、异构同步平台，通常都依赖 binlog。</p><p>binlog 的核心特点是“逻辑”。它关注的是执行了什么 DDL、什么 DML、哪些行发生了变化，而不是某个数据页的某个偏移量如何修改。因此 binlog 很适合给外部系统消费：从库可以根据 binlog 重放主库变更，数据订阅系统可以把 binlog 转成消息事件，下游搜索引擎或缓存系统也可以据此增量更新。</p><h3 id="_1-三种-binlog-格式" tabindex="-1">1. 三种 binlog 格式 <a class="header-anchor" href="#_1-三种-binlog-格式" aria-label="Permalink to &quot;1\\. 三种 binlog 格式&quot;">​</a></h3><p>binlog 常见格式有 Statement、Row 和 Mixed。Statement 记录 SQL 语句本身，日志量较小，但遇到 now()、uuid()、非确定性函数、触发器副作用、不同执行计划等情况时，主从结果可能不一致。Row 记录行级变更，能准确描述每一行改前改后的结果，复制更可靠，但日志量可能明显增大。Mixed 是折中模式，MySQL 会在普通场景使用 Statement，在可能产生不确定性的场景切换到 Row。</p><p>面试中建议把 Row 作为生产环境更常见、更可靠的答案。尤其在主从复制、数据订阅、审计回放等场景里，Row 格式能减少“同一条 SQL 在不同节点执行出不同结果”的风险。它的代价是日志体积更大，因此需要配合合理的 binlog 保留策略、磁盘监控和归档策略。</p><h3 id="_2-binlog-可以做什么恢复" tabindex="-1">2. binlog 可以做什么恢复 <a class="header-anchor" href="#_2-binlog-可以做什么恢复" aria-label="Permalink to &quot;2\\. binlog 可以做什么恢复&quot;">​</a></h3><p>binlog 支持逻辑恢复，常见做法是先用全量备份恢复到某个基线，再按时间点或位点重放 binlog。比如误删数据后，可以恢复最近一次全量备份，再重放误操作之前的 binlog，尽量把数据恢复到出错前的状态。这里要注意，binlog 不是替代备份的工具，它更像全量备份之后的增量恢复材料。</p><p>binlog 也不是 InnoDB 崩溃恢复的核心依据。实例宕机重启后，InnoDB 首先依赖 redo log 和 undo log 判断数据页如何恢复；binlog 更偏外部逻辑链路，主要用于复制和逻辑层恢复。把“宕机恢复”和“误操作恢复”区分清楚，是日志题的高频考点。</p><h2 id="三、redo-log-wal-思想下的崩溃恢复日志" tabindex="-1">三、redo log：WAL 思想下的崩溃恢复日志 <a class="header-anchor" href="#三、redo-log-wal-思想下的崩溃恢复日志" aria-label="Permalink to &quot;三、redo log：WAL 思想下的崩溃恢复日志&quot;">​</a></h2><p>redo log 是 InnoDB 的重做日志，记录数据页被如何修改。它解决的问题是：事务提交后，即使修改过的数据页还停留在 Buffer Pool 中、尚未刷回磁盘，只要 redo log 已经持久化，数据库宕机后仍然能重放这些修改，保证已提交事务不丢。</p><p>redo log 背后的核心思想是 WAL（Write-Ahead Logging，预写日志）。所谓预写，就是先把修改意图以顺序写的方式写入日志，再择机把真正的数据页刷回磁盘。这样可以把大量随机写转化为更友好的顺序写，同时让脏页刷盘变成后台批量行为。</p><h3 id="_1-为什么不直接刷数据页" tabindex="-1">1. 为什么不直接刷数据页 <a class="header-anchor" href="#_1-为什么不直接刷数据页" aria-label="Permalink to &quot;1\\. 为什么不直接刷数据页&quot;">​</a></h3><p>InnoDB 默认页大小是 16KB，一条更新语句可能只修改其中几行。如果每次事务提交都同步刷整个数据页，磁盘会承受大量随机写，吞吐会很差。并且同一个事务可能修改多个页，这些页在磁盘上并不连续，逐页同步刷盘会放大延迟。</p><p>redo log 的设计把“提交时必须同步完成的动作”压缩到日志持久化上。数据页可以先留在 Buffer Pool 中成为脏页，之后由后台刷脏线程、checkpoint 推进机制或内存压力触发刷盘。只要 redo log 中保存了足够的重做信息，即使脏页没有及时落盘，重启后也能恢复。</p><h3 id="_2-redo-log-buffer、刷盘与参数边界" tabindex="-1">2. redo log buffer、刷盘与参数边界 <a class="header-anchor" href="#_2-redo-log-buffer、刷盘与参数边界" aria-label="Permalink to &quot;2\\. redo log buffer、刷盘与参数边界&quot;">​</a></h3><p>事务执行过程中，redo 记录会先写入 redo log buffer，再根据提交策略刷到操作系统缓存和磁盘文件。常见参数 innodb_flush_log_at_trx_commit 决定提交时 redo 的刷盘强度：设置为 1 时，每次提交都写入并刷盘，持久性最好；设置为 2 时，每次提交写入操作系统缓存，通常每秒刷盘一次；设置为 0 时，每秒写入并刷盘一次，性能更高但宕机丢失风险更大。</p><p>面试回答时不要只背参数值，要说清取舍：金融支付、订单扣款等强一致场景通常倾向于 1；对极端吞吐要求更高且可以容忍少量数据丢失的日志型业务，才可能考虑放宽。真实生产中还要结合磁盘缓存、电源保护、云盘语义和高可用架构一起判断。</p><h2 id="四、redo-与-binlog-的两阶段提交" tabindex="-1">四、redo 与 binlog 的两阶段提交 <a class="header-anchor" href="#四、redo-与-binlog-的两阶段提交" aria-label="Permalink to &quot;四、redo 与 binlog 的两阶段提交&quot;">​</a></h2><p>redo log 和 binlog 分属 InnoDB 引擎层和 MySQL Server 层。一个事务提交时，如果只写 redo 不写 binlog，主库本地可能恢复出这次修改，但从库和订阅系统看不到；如果只写 binlog 不提交 redo，从库可能重放了主库本地并未真正提交的修改。这两种情况都会造成主从不一致。</p><p>因此 MySQL 使用两阶段提交协调二者。典型流程是：InnoDB 先把 redo log 写到 prepare 状态；Server 层写 binlog；binlog 写成功后，InnoDB 再把 redo log 写成 commit 状态。崩溃恢复时，如果发现 redo 是 prepare 状态，就需要结合 binlog 判断事务是否应该提交：binlog 完整存在，则提交；binlog 不完整或不存在，则回滚。</p><p>这里的重点不是把流程背成口令，而是理解 prepare 的意义。prepare 让 InnoDB 暂时把事务放在“可以提交但尚未最终提交”的中间状态，给 Server 层写 binlog 留出协调窗口。这样一来，即使崩溃发生在两个日志之间，恢复流程也能根据日志完整性作出一致判断。</p><h2 id="五、undo-log-回滚与-mvcc-的旧版本依据" tabindex="-1">五、undo log：回滚与 MVCC 的旧版本依据 <a class="header-anchor" href="#五、undo-log-回滚与-mvcc-的旧版本依据" aria-label="Permalink to &quot;五、undo log：回滚与 MVCC 的旧版本依据&quot;">​</a></h2><p>undo log 记录数据修改前的旧版本。事务执行 UPDATE、DELETE、INSERT 时，InnoDB 会生成相应 undo 信息：更新时记录旧值，删除时记录可恢复的信息，插入时记录可撤销插入的标记。事务回滚时，InnoDB 按 undo log 反向执行，把数据恢复到事务开始前或保存点之前的状态。</p><p>undo log 同时支撑 MVCC。InnoDB 行记录中有隐藏事务 ID 和回滚指针，回滚指针可以串起 undo 版本链。一致性读不一定读取最新版本，而是根据 Read View 判断最新版本是否可见；如果不可见，就沿着 undo 版本链向旧版本查找，直到找到对当前事务可见的版本。</p><h3 id="_1-undo-与原子性" tabindex="-1">1. undo 与原子性 <a class="header-anchor" href="#_1-undo-与原子性" aria-label="Permalink to &quot;1\\. undo 与原子性&quot;">​</a></h3><p>原子性要求事务中的操作要么全部成功，要么全部失败。undo log 正是撤销已执行修改的基础。比如转账事务中已经扣减 A 账户余额，但给 B 账户加钱失败，事务回滚时就可以根据 undo 把 A 的余额恢复。没有 undo，数据库只能知道“事务失败了”，却不知道如何恢复已经被改过的数据。</p><h3 id="_2-undo-与-purge" tabindex="-1">2. undo 与 purge <a class="header-anchor" href="#_2-undo-与-purge" aria-label="Permalink to &quot;2\\. undo 与 purge&quot;">​</a></h3><p>undo 不能在事务提交后立即删除，因为其他正在执行的一致性读可能还需要旧版本。只有当系统确认没有活跃事务需要这些版本时，purge 线程才会清理无用 undo。长事务会拖住 Read View，使旧版本长期不能清理，导致 undo 膨胀、历史版本链变长，最终影响查询和存储空间。</p><h2 id="六、三类日志的对比边界" tabindex="-1">六、三类日志的对比边界 <a class="header-anchor" href="#六、三类日志的对比边界" aria-label="Permalink to &quot;六、三类日志的对比边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>binlog</th><th>redo log</th><th>undo log</th></tr></thead><tbody><tr><td>所在层次</td><td>MySQL Server 层</td><td>InnoDB 引擎层</td><td>InnoDB 引擎层</td></tr><tr><td>记录内容</td><td>逻辑变更、行变更事件</td><td>数据页物理修改</td><td>修改前的旧版本</td></tr><tr><td>主要用途</td><td>主从复制、订阅、逻辑恢复</td><td>崩溃恢复、持久性</td><td>回滚、MVCC、一致性读</td></tr><tr><td>写入方式</td><td>追加写，文件滚动</td><td>循环写，checkpoint 推进</td><td>形成版本链，后续 purge</td></tr><tr><td>面试误区</td><td>不是崩溃恢复主力</td><td>不是主从复制主力</td><td>不是复制日志</td></tr></tbody></table><p>三者共同参与事务可靠性，但各自回答的问题不同。binlog 回答“这次逻辑变更如何传给别人”；redo log 回答“本机宕机后已提交修改如何找回来”；undo log 回答“失败事务如何撤销、旧版本如何读到”。面试中只要能围绕这三个问题展开，答案就不会散。</p><h2 id="七、使用边界与常见风险" tabindex="-1">七、使用边界与常见风险 <a class="header-anchor" href="#七、使用边界与常见风险" aria-label="Permalink to &quot;七、使用边界与常见风险&quot;">​</a></h2><p>日志机制不能替代业务层的幂等和备份策略。binlog 可以帮助恢复误操作，但前提是有可用全量备份、binlog 没被清理、恢复目标时间点明确。redo log 能保证已提交事务不丢，但刷盘参数过于激进地追求性能时，仍可能在操作系统或硬件崩溃场景下扩大风险。undo log 能支撑回滚和 MVCC，但长事务会让 undo 长期保留，拖慢 purge。</p><p>生产中还要关注日志空间。redo log 空间不足会迫使 checkpoint 推进，写入可能抖动；binlog 保留时间过长会占用磁盘，保留时间过短又会影响复制延迟节点和数据恢复；undo 表空间持续膨胀则往往提示存在长事务或清理压力。日志不是越多越安全，而是要和业务恢复目标、磁盘容量、复制链路一起设计。</p><h2 id="八、面试表达模板" tabindex="-1">八、面试表达模板 <a class="header-anchor" href="#八、面试表达模板" aria-label="Permalink to &quot;八、面试表达模板&quot;">​</a></h2><p>如果被问“redo log 如何保证持久性”，可以这样答：InnoDB 修改数据时先在 Buffer Pool 中改页，同时生成 redo 记录。事务提交时按刷盘策略把 redo 持久化，而数据页可以稍后由后台线程刷盘。宕机后，如果数据页没有包含已提交修改，InnoDB 可以根据 redo log 重放，所以 redo log 保证的是已提交事务在崩溃后的可恢复性。</p><p>如果被问“binlog 和 redo log 为什么要两阶段提交”，可以这样答：binlog 属于 Server 层，redo log 属于 InnoDB 层，二者分别服务复制和崩溃恢复。事务提交时如果一个成功一个失败，就可能出现主库本地状态和从库重放状态不一致。两阶段提交先让 redo 进入 prepare，再写 binlog，最后提交 redo，崩溃恢复时通过 redo prepare 状态和 binlog 完整性判断事务最终提交还是回滚。</p><p>如果被问“undo log 的作用”，可以这样答：undo log 记录修改前的旧版本，一方面事务失败或显式回滚时可以按 undo 撤销修改，保证原子性；另一方面一致性读可以沿着 undo 版本链找到对当前 Read View 可见的历史版本，所以 undo 也是 MVCC 的基础。</p><h2 id="九、常见追问与练习" tabindex="-1">九、常见追问与练习 <a class="header-anchor" href="#九、常见追问与练习" aria-label="Permalink to &quot;九、常见追问与练习&quot;">​</a></h2><p><strong>追问 1：redo log 写成功但数据页没刷盘，宕机会不会丢数据？</strong> 不会丢已提交数据。只要 redo log 按提交策略持久化成功，重启时 InnoDB 可以重放 redo，把数据页恢复到提交后的状态。数据页是否在提交瞬间刷盘不是持久性的唯一依据。</p><p><strong>追问 2：binlog 能不能替代 redo log？</strong> 不能。binlog 是逻辑日志，主要给复制、订阅和逻辑恢复使用；redo log 是 InnoDB 的物理重做日志，面向崩溃恢复。两者记录粒度、所在层次和恢复目标不同。</p><p><strong>练习 1：为什么长事务可能导致 undo 空间膨胀？</strong> 答案：长事务持有较早的 Read View，系统必须保留它可能读到的历史版本，purge 线程不能清理这些 undo 记录。长事务越久，旧版本链越长，undo 空间越容易膨胀。</p><p><strong>练习 2：事务提交时 redo 已经 prepare，binlog 也写完，但 redo 还没 commit 就宕机，恢复时应该怎么办？</strong> 答案：恢复时如果发现 redo 处于 prepare 状态，会检查对应 binlog 是否完整。binlog 完整说明逻辑提交已经对外成立，应把事务提交；如果 binlog 不完整，则回滚事务。</p>',56)])])}const _=e(t,[["render",g]]);export{c as __pageData,_ as default};
